class ComponentIconLibrary extends HTMLElement {
  getIconSVG(iconName) {
    if (iconName in Icons) {
      return Icons[iconName];
    }
    return undefined;
  }
  connectedCallback() {
    const iconName = this.name || 'empty';
    this.innerHTML =
      this.getIconSVG(iconName) ??
      `<sc-icon size=${this.customStyle?.size} name=${iconName}></sc-icon>`;
  }
}
if (!window.customElements.get('icon-component')) {
  window.customElements.define('icon-component', ComponentIconLibrary);
}
